import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { buildSync } from "esbuild";
import { afterAll, describe, expect, it } from "vitest";
import { analyzeJavaScriptTree, asarTree, type JsAppInfo } from "../src/javascript/app.js";
import { interfaceMap } from "../src/javascript/interfaces.js";
import { simpleRegex } from "../src/javascript/resolve.js";
import { scanJavaScript } from "../src/javascript/scan.js";
import { Session } from "../src/session.js";
import { buildAsar } from "./fixtures/asar.js";
import { timeLimit } from "./timeLimit.js";

/**
 * IPC channel names generated by a channel-registry function: a function that builds an object of
 * channel names from a prefix and a list, called once per group. Read by the abstract evaluation
 * of function bodies in resolve.ts; nothing of these sources is run.
 */

/** The registry, as CommonJS: three ways of building the same kind of table. */
const CHANNELS_CJS = `// Channel names: "<prefix>:<kebab-case name>", built once from a list.
function kebab(name) {
  return name.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase());
}
function defineChannels(prefix, names) {
  const out = {};
  for (const name of names) out[name] = \`\${prefix}:\${kebab(name)}\`;
  return out;
}
const BOARD = defineChannels("board", ["list", "moveCard", "addColumn"]);
const CARD = Object.fromEntries(["open", "archive"].map((n) => [n, "card:" + n]));
const LANE = (() => {
  const t = {};
  ["create", "rename"].forEach((n) => {
    t[n] = "lane:".concat(n.toUpperCase());
  });
  return t;
})();
module.exports = { BOARD, CARD, LANE };
`;

/** The same registry as an ES module. */
const CHANNELS_ESM = CHANNELS_CJS.replace(
  "function defineChannels",
  "export function defineChannels",
)
  .replace("const BOARD", "export const BOARD")
  .replace("const CARD", "export const CARD")
  .replace("const LANE", "export const LANE")
  .replace("module.exports = { BOARD, CARD, LANE };\n", "");

const MAIN = (load: string) => `${load}
// ipcMain.handle(BOARD.archiveAll, …) is not registered: this is a comment
const help = "ipcMain.handle('board:delete-card', fn)";
console.log(help, "board:delete-card");
ipcMain.handle(BOARD.list, () => []);
ipcMain.handle(BOARD.moveCard, (e, id, to) => ({ id, to }));
ipcMain.on(CARD.archive, () => {});
ipcMain.handle(LANE.rename, () => true);
app.whenReady().then(() => {
  const win = new BrowserWindow({
    webPreferences: { preload: path.join(__dirname, "preload.js"), contextIsolation: true },
  });
  win.webContents.send(BOARD.addColumn, { id: 1 });
});
`;

const PRELOAD = (load: string) => `${load}
contextBridge.exposeInMainWorld("board", {
  list: () => ipcRenderer.invoke(BOARD.list),
  move: (id, to) => ipcRenderer.invoke(BOARD.moveCard, id, to),
  onColumn: (fn) => ipcRenderer.on(BOARD.addColumn, (_e, c) => fn(c)),
  archive: () => ipcRenderer.send(CARD.archive),
  renameLane: () => ipcRenderer.invoke(LANE.rename),
});
`;

const CJS: Record<string, string> = {
  "channels.js": CHANNELS_CJS,
  "main.js": MAIN(
    'const { app, ipcMain, BrowserWindow } = require("electron");\nconst path = require("path");\nconst { BOARD, CARD, LANE } = require("./channels");',
  ),
  "preload.js": PRELOAD(
    'const { contextBridge, ipcRenderer } = require("electron");\nconst { BOARD, CARD, LANE } = require("./channels");',
  ),
};

const ESM: Record<string, string> = {
  "channels.js": CHANNELS_ESM,
  "main.js": MAIN(
    'import { app, ipcMain, BrowserWindow } from "electron";\nimport path from "path";\nimport { BOARD, CARD, LANE } from "./channels.js";',
  ),
  "preload.js": PRELOAD(
    'import { contextBridge, ipcRenderer } from "electron";\nimport { BOARD, CARD, LANE } from "./channels.js";',
  ),
};

/** What every variant must report: channel → [senders, receivers]. */
const EXPECTED = {
  "board:add-column": [["main.js"], ["preload.js"]],
  "board:list": [["preload.js"], ["main.js"]],
  "board:move-card": [["preload.js"], ["main.js"]],
  "card:archive": [["preload.js"], ["main.js"]],
  "lane:RENAME": [["preload.js"], ["main.js"]],
};
/** Look-alikes and names the code defines but never registers. */
const NEVER = ["board:delete-card", "board:archive-all", "card:open", "lane:CREATE"];

const dir = mkdtempSync(join(tmpdir(), "hexvero-registry-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

function analyze(files: Record<string, string>): JsAppInfo {
  return analyzeJavaScriptTree(
    asarTree(
      buildAsar({
        "package.json": JSON.stringify({
          name: "board",
          main: "main.js",
          dependencies: { electron: "^30.0.0" },
        }),
        ...files,
      }),
      "app.asar",
    ),
  );
}

/** main.js and preload.js bundled by esbuild from the sources, optionally minified. */
function bundled(sources: Record<string, string>, minify: boolean): Record<string, string> {
  const src = mkdtempSync(join(dir, "src-"));
  for (const [name, text] of Object.entries(sources)) {
    mkdirSync(dirname(join(src, name)), { recursive: true });
    writeFileSync(join(src, name), text);
  }
  const out: Record<string, string> = {};
  for (const entry of ["main.js", "preload.js"]) {
    const outfile = join(src, "out", entry);
    buildSync({
      entryPoints: [join(src, entry)],
      bundle: true,
      minify,
      platform: "node",
      format: "cjs",
      external: ["electron"],
      outfile,
      logLevel: "silent",
    });
    out[entry] = readFileSync(outfile, "utf8");
  }
  return out;
}

const channelsOf = (info: JsAppInfo): Record<string, string[][]> =>
  Object.fromEntries(info.ipcChannels.map((c) => [c.channel, [c.senders, c.receivers]]));

function expectRegistry(info: JsAppInfo): void {
  const got = channelsOf(info);
  for (const [channel, ends] of Object.entries(EXPECTED)) expect(got[channel]).toEqual(ends);
  for (const name of NEVER) expect(got[name]).toBeUndefined();
  expect(info.limitations.map((l) => l.code)).not.toContain("ipc_channel_unresolved");
  // every member of the bridge is joined to its main-process end
  const rows = interfaceMap(info, info.limitations);
  expect(rows.map((r) => `${r.member} ${r.channel} ${r.direction} ${r.link}`)).toEqual([
    "list board:list to-main resolved",
    "move board:move-card to-main resolved",
    "onColumn board:add-column to-renderer resolved",
    "archive card:archive to-main resolved",
    "renameLane lane:RENAME to-main resolved",
  ]);
}

describe("channels from a channel-registry function", () => {
  it("reads them across CommonJS modules, with senders, receivers and linked interface rows", () => {
    const info = analyze(CJS);
    expectRegistry(info);
    // said how: by evaluating the registry, not as a literal
    const row = info.modules
      .find((m) => m.id === "main.js")!
      .ipc.find((u) => u.channel === "board:list");
    expect(row).toMatchObject({
      channel: "board:list",
      via: "resolved",
      resolution: { method: "evaluated" },
    });
  });

  it("reads them across ES modules", () => {
    expectRegistry(analyze(ESM));
  });

  it("reads them bundled by esbuild, from ES modules and from CommonJS wrappers", () => {
    expectRegistry(analyze(bundled(ESM, false)));
    expectRegistry(analyze(bundled(CJS, false)));
  });

  it("reads them minified, with every binding renamed", () => {
    const files = bundled(ESM, true);
    expect(files["main.js"]).not.toContain("defineChannels");
    expectRegistry(analyze(files));
    expectRegistry(analyze(bundled(CJS, true)));
  });

  it("reads them in a webpack-style bundle whose modules are functions of one file", () => {
    const registry = CHANNELS_CJS.replace("module.exports = { BOARD, CARD, LANE };\n", "");
    const main = `(() => {
  var __webpack_modules__ = {
    "electron": (module) => { module.exports = require("electron"); },
  };
  function __webpack_require__(id) {
    var module = { exports: {} };
    __webpack_modules__[id](module, module.exports, __webpack_require__);
    return module.exports;
  }
  var __webpack_exports__ = {};
  (() => {
    "use strict";
    // ./src/channels.js
${registry}
    // ./src/main.js
    const external_electron_ = __webpack_require__("electron");
    external_electron_.ipcMain.handle(BOARD.moveCard, () => 1);
    external_electron_.ipcMain.handle(CARD.archive, () => 1);
  })();
})();
`;
    const got = channelsOf(analyze({ "main.js": main }));
    expect(Object.keys(got).toSorted()).toEqual(["board:move-card", "card:archive"]);
  });

  it("does not depend on statement order, semicolons or the loop form", () => {
    const files = {
      "main.js": `const { ipcMain } = require("electron")
app.whenReady().then(() => {
  ipcMain.handle(TOOLS.zoomIn, f)
  ipcMain.handle(TOOLS.zoomOut, f)
  ipcMain.handle(VIEWS.splitPane, f)
})
const TOOLS = make("tools", ["zoomIn", "zoomOut"])
const VIEWS = byMap("view", ["splitPane"])
function make(prefix, names) {
  const table = {}
  names.forEach(function (name) {
    table[name] = [prefix, name.replace(/([a-z])([A-Z])/g, "$1-$2")].join(":")
  })
  return table
}
function byMap(prefix, names) {
  const pairs = names.map((n) => [n, prefix + "." + n.slice(0, 5)])
  return Object.fromEntries(pairs)
}
`,
    };
    const info = analyze(files);
    // `$1-$2` is outside the subset (a replacement with $): those channels stay unknown
    expect(Object.keys(channelsOf(info)).toSorted()).toEqual(["view.split"]);
    const unresolved = info.limitations.find((l) => l.code === "ipc_channel_unresolved");
    expect(unresolved?.message).toContain("evaluation stopped");

    const kebab = files["main.js"].replace(
      'name.replace(/([a-z])([A-Z])/g, "$1-$2")',
      'name.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase())',
    );
    expect(Object.keys(channelsOf(analyze({ "main.js": kebab }))).toSorted()).toEqual([
      "tools:zoom-in",
      "tools:zoom-out",
      "view.split",
    ]);
  });

  it("reads a local of the function that shadows the registry, not the registry", () => {
    const info = analyze({
      "main.js": `const { ipcMain } = require("electron");
function defineChannels(prefix, names) {
  const out = {};
  for (const name of names) out[name] = prefix + ":" + name;
  return out;
}
const BOARD = defineChannels("board", ["list"]);
function legacy() {
  const BOARD = { list: "legacy:list" };
  ipcMain.handle(BOARD.list, f);
}
function other(defineChannels) {
  const X = defineChannels("x", ["y"]);
  ipcMain.handle(X.y, f);
}
ipcMain.handle(BOARD.list, f);
`,
    });
    const got = Object.keys(channelsOf(info)).toSorted();
    expect(got).toEqual(["board:list", "legacy:list"]);
    // the parameter that shadows the registry function is not that function
    expect(got).not.toContain("x:y");
  });

  it("does not take a same-named object of another module, or a non-IPC call, for a channel", () => {
    const info = analyze({
      ...CJS,
      // its own BOARD, used for something else
      "ui.js":
        'const BOARD = { list: "ui:list" };\nmodule.exports = { BOARD };\ndocument.title = BOARD.list;',
      "renderer.js":
        'const { BOARD } = require("./ui");\nconst store = { list: () => 1 };\nstore.list(BOARD.list);',
    });
    expectRegistry(info);
    expect(channelsOf(info)["ui:list"]).toBeUndefined();
  });

  it("ends on circular imports and says the channels are not known", () => {
    const info = analyze({
      "main.js":
        'const { ipcMain } = require("electron");\nconst { A } = require("./a");\nipcMain.handle(A.go, f);',
      "a.js": 'const { B } = require("./b");\nmodule.exports = { A: B };',
      "b.js": 'const { A } = require("./a");\nmodule.exports = { B: A };',
    });
    expect(info.ipcChannels).toEqual([]);
    // a function that calls itself to build its table is a cycle
    const self = analyze({
      "main.js": `const { ipcMain } = require("electron");
function grow(names) { const o = {}; for (const n of names) o[n] = grow([n]).x; return o; }
const T = grow(["x"]);
ipcMain.handle(T.x, f);`,
    });
    expect(self.ipcChannels).toEqual([]);
    expect(self.limitations.find((l) => l.code === "ipc_channel_unresolved")?.message).toContain(
      "cycle",
    );
  });

  it("gives up on a value set over the limit, and says so", () => {
    const names = Array.from({ length: 300 }, (_, i) => `"n${i}"`).join(", ");
    const info = analyze({
      "main.js": `const { ipcMain } = require("electron");
function defineChannels(prefix, names) {
  const out = {};
  for (const name of names) out[name] = prefix + ":" + name;
  return out;
}
const BIG = defineChannels("big", [${names}]);
ipcMain.handle(BIG.n1, f);
const P = ["a", "b", "c", "d", "e", "f", "g", "h", "i"];
function pick(xs) { const o = {}; for (const x of xs) o[x] = x; return o; }
`,
    });
    expect(info.ipcChannels).toEqual([]);
    expect(info.limitations.find((l) => l.code === "ipc_channel_unresolved")?.message).toContain(
      "too many values",
    );
  });

  it("keeps values known only at run time unknown", () => {
    const info = analyze({
      "main.js": `const { ipcMain } = require("electron");
function defineChannels(prefix, names) {
  const out = {};
  for (const name of names) out[name] = prefix + ":" + name;
  return out;
}
const ENV = defineChannels(process.env.CHANNEL_PREFIX, ["get"]);
const RND = defineChannels("r" + Math.random(), ["get"]);
async function remote() {
  const names = await fetch("https://example.test/names.json");
  return defineChannels("remote", names);
}
const REMOTE = remote();
ipcMain.handle(ENV.get, f);
ipcMain.handle(RND.get, f);
ipcMain.handle(REMOTE.get, f);
`,
    });
    expect(info.ipcChannels).toEqual([]);
    const message = info.limitations.find((l) => l.code === "ipc_channel_unresolved")?.message;
    expect(message).toContain("3 IPC call(s)");
    expect(message).toContain("runtime value: process");
  });

  it("never runs the analyzed code", () => {
    // Code that would throw, loop forever or touch the file system if it ran: read, not run.
    const info = analyze({
      "main.js": `const { ipcMain } = require("electron");
function defineChannels(prefix, names) {
  const out = {};
  for (const name of names) out[name] = prefix + ":" + name;
  return out;
}
function evil(names) { require("fs").rmSync("/", { recursive: true }); while (true) {} }
const SAFE = defineChannels("safe", ["ok"]);
const BAD = evil(["x"]);
ipcMain.handle(SAFE.ok, f);
ipcMain.handle(BAD.x, f);
`,
    });
    expect(info.ipcChannels.map((c) => c.channel)).toEqual(["safe:ok"]);
    expect(info.limitations.find((l) => l.code === "ipc_channel_unresolved")?.message).toContain(
      "unsupported statement",
    );
  });

  it("shows a channel the registry gains in a later version as added", async () => {
    const v2 = {
      ...CJS,
      "channels.js": CJS["channels.js"]!.replace('"addColumn"]', '"addColumn", "deleteCard"]'),
      "main.js": `${CJS["main.js"]!}\nipcMain.handle(BOARD.deleteCard, () => true);\n`,
    };
    writeFileSync(join(dir, "v1.asar"), appAsar(CJS));
    writeFileSync(join(dir, "v2.asar"), appAsar(v2));
    const saved = process.env["HEXVERO_CACHE_DIR"];
    process.env["HEXVERO_CACHE_DIR"] = join(dir, "cache");
    try {
      const session = new Session();
      const a = await session.open(join(dir, "v1.asar"));
      const b = await session.open(join(dir, "v2.asar"));
      const { diff } = await session.compareCollection(a.id, b.id, "ipcChannels");
      expect(diff.added).toEqual(["board:delete-card"]);
      expect([diff.removed, diff.changed, diff.unknown]).toEqual([[], [], []]);
    } finally {
      if (saved === undefined) delete process.env["HEXVERO_CACHE_DIR"];
      else process.env["HEXVERO_CACHE_DIR"] = saved;
    }
  });
});

function appAsar(files: Record<string, string>): Uint8Array {
  return buildAsar({
    "package.json": JSON.stringify({
      name: "board",
      main: "main.js",
      dependencies: { electron: "^30.0.0" },
    }),
    ...files,
  });
}

/** The channels of a single file's IPC calls, in order (null: not read). */
const channels = (source: string): Array<string | null> =>
  scanJavaScript(`const { ipcMain } = require("electron");\n${source}`).ipc.map((u) => u.channel);

describe("the evaluation subset", () => {
  it("applies the listed string operations", () => {
    expect(
      channels(`function f(p) { const o = {}; o.a = p.toUpperCase().slice(0, 2).concat("-", "x"); o.b = "a_b_c".split("_").join("."); o.c = "x-y-x".replaceAll("x", "z"); o.d = "Ab".replace(/b/i, "c"); return o; }
const T = f("main");
ipcMain.on(T.a, g); ipcMain.on(T.b, g); ipcMain.on(T.c, g); ipcMain.on(T.d, g);`),
    ).toEqual(["MA-x", "a.b.c", "z-y-z", "Ac"]);
  });

  it("writes only to objects the function created", () => {
    expect(
      channels(`const SHARED = {};
function f(names) { for (const n of names) SHARED[n] = "s:" + n; return SHARED; }
const T = f(["a"]);
ipcMain.on(T.a, g);`),
    ).toEqual([null]);
    expect(
      channels(`function f(target, names) { for (const n of names) target[n] = "s:" + n; return target; }
const T = f({}, ["a"]);
ipcMain.on(T.a, g);`),
    ).toEqual([null]);
  });

  it("stops at statements outside the subset", () => {
    for (const body of [
      'if (names.length) out.x = "a:x";',
      'try { out.x = "a:x"; } catch {}',
      'for (let i = 0; i < names.length; i++) out[names[i]] = "a:" + names[i];',
      'while (false) out.x = "a:x";',
      'register(out); out.x = "a:x";',
      'count++; out.x = "a:x";',
    ]) {
      const scan = scanJavaScript(`const { ipcMain } = require("electron");
function f(names) { const out = {}; let count = 0; ${body} return out; }
const T = f(["x"]);
ipcMain.on(T.x, g);`);
      expect(scan.ipc.map((u) => u.channel)).toEqual([null]);
      expect(scan.ipc[0]?.reason).toMatch(/^evaluation stopped: /);
    }
  });

  it("builds only simple regular expressions", () => {
    expect(simpleRegex("/[A-Z]/g")?.source).toBe("[A-Z]");
    expect(simpleRegex("/^[a-z0-9_]+$/gi")?.flags).toBe("gi");
    expect(simpleRegex("/\\s+/g")).not.toBeNull();
    for (const bad of ["/(a+)+$/", "/a|b/", "/(?=x)/", "/\\1/", "/a{2,}/", "/x/y", "/[a-z]/gm"])
      expect(simpleRegex(bad)).toBeNull();
  });
});

/** The first IPC row of a file that declares `T` and registers `T.x`. */
const scan = (body: string) =>
  scanJavaScript(`const { ipcMain } = require("electron");\n${body}\nipcMain.on(T.x, g);`).ipc[0]!;

describe("the evaluation is bounded on hostile input", () => {
  it("never builds a regular expression that can backtrack badly", { timeout: 3000 }, () => {
    const many = `/${"a*".repeat(16)}b/g`;
    expect(simpleRegex(many)).toBeNull();
    expect(simpleRegex("/a+b*/g")).toBeNull(); // two quantified atoms
    expect(simpleRegex("/[^a-z0-9]+/gi")).not.toBeNull(); // one is fine
    const row = scan(
      `function f() { const o = {}; o.x = "${"a".repeat(900)}".replace(${many}, "x"); return o; }\nconst T = f();`,
    );
    expect(row.channel).toBeNull();
    expect(row.reason).toContain("unsupported regular expression");
  });

  it("stops strings that grow in a loop or by +=", { timeout: 3000 }, () => {
    const doubling = Array.from({ length: 60 }, (_, i) => `"${i}"`).join(", ");
    const loop = scan(
      `function f(L) { const o = { x: "ab" }; for (const i of L) o.x = o.x + o.x; return o; }\nconst T = f([${doubling}]);`,
    );
    expect(loop.channel).toBeNull();
    expect(loop.reason).toContain("too many values");
    const plus = scan(
      `function f() { const o = {}; let s = "ab"; ${"s += s; ".repeat(60)}o.x = s; return o; }\nconst T = f();`,
    );
    expect(plus.channel).toBeNull();
    expect(plus.reason).toContain("too many values");
  });

  it("stops at deeply nested blocks instead of overflowing the stack", { timeout: 5000 }, () => {
    const row = scan(
      `function f() { const o = {}; ${"{".repeat(20_000)} o.x = "a:x"; ${"}".repeat(20_000)} return o; }\nconst T = f();`,
    );
    expect(row.channel).toBeNull();
    expect(row.reason).toContain("depth limit");
    // and parentheses deep enough to overflow a recursive reader
    const parens = scan(`const T = { x: ${"(".repeat(50_000)}"a:x"${")".repeat(50_000)} };`);
    expect(parens.channel === null || parens.channel === "a:x").toBe(true);
  });
});

describe("a registry function of another module, without bundling", () => {
  it("is not silent: the call is named in ipc_channel_unresolved with the reason", () => {
    const info = analyze({
      "util.js":
        'function defineChannels(prefix, names) { const out = {}; for (const n of names) out[n] = prefix + ":" + n; return out; }\nmodule.exports = { defineChannels };',
      "channels.js":
        'const { defineChannels } = require("./util");\nconst BOARD = defineChannels("board", ["list"]);\nmodule.exports = { BOARD };',
      "main.js":
        'const { ipcMain } = require("electron");\nconst { BOARD } = require("./channels");\nipcMain.handle(BOARD.list, () => []);',
    });
    const message = info.limitations.find((l) => l.code === "ipc_channel_unresolved")?.message;
    expect(message).toContain("ipcMain.handle at main.js:3");
    expect(message).toContain("another module");
  });
});

/** The channel of an IPC call whose channel argument is the given literal. */
const literalAt = (literal: string) =>
  scanJavaScript(`const { ipcMain } = require("electron");\nipcMain.on(${literal}, g);`).ipc[0]!
    .channel;

/**
 * Review findings: each case is what the code really does at run time; the evaluation must report
 * that channel or nothing (null), never another one. A false channel is worse than a miss.
 */
const truthOrNothing = (source: string, truth: string | null): void => {
  const row = scanJavaScript(
    `const { ipcMain } = require("electron");\n${source}\nipcMain.on(T.x, g);`,
  ).ipc[0]!;
  expect([truth, null]).toContain(row.channel);
};

describe("review: no false channel from the evaluation", () => {
  it(
    "H1: counts every quantifier, also on an escaped backslash, and charges regex work",
    {
      timeout: 3000,
    },
    () => {
      const lit = `/${"\\\\?".repeat(20)}${"\\\\".repeat(12)}/g`;
      expect(simpleRegex(lit)).toBeNull();
      expect(simpleRegex("/\\\\?x/g")).not.toBeNull(); // one quantified atom
      expect(simpleRegex("/a?\\??/g")).toBeNull(); // two, one of them an escaped `?`
      const subject = ("\\\\".repeat(11) + "x").repeat(80);
      const started = performance.now();
      const row = scan(
        `function f() { const o = {}; o.x = "${subject}"${`.replace(${lit}, "y")`.repeat(20)}; return o; }\nconst T = f();`,
      );
      expect(performance.now() - started).toBeLessThan(timeLimit(1500));
      expect(row.channel).toBeNull();
    },
  );

  it("H2: stops when an expression it cannot read may have effects", () => {
    const cases: Array<[string, string | null]> = [
      [
        `function f(){ const parts = ["a"]; const n = parts.push("b"); const o = {}; o.x = parts.join(":"); return o; }\nconst T = f();`,
        "a:b",
      ],
      [
        `function f(){ const o = {x:"a"}; const z = Object.assign(o, {x:"b"}); return o; }\nconst T = f();`,
        "b",
      ],
      [
        `function f(){ let s = "a"; const z = (s = "b"); const o = {}; o.x = s; return o; }\nconst T = f();`,
        "b",
      ],
      [`function f(){ const o = {x:"a"}; const d = delete o.x; return o; }\nconst T = f();`, null],
      [
        `function add(o){ o.x = "b"; } function f(){ const o = {x:"a"}; const r = add(o); return o; }\nconst T = f();`,
        "b",
      ],
      [
        `function f(){ const a = ["a"]; const b = a; const n = b.push("c"); const o = {}; o.x = a.join(); return o; }\nconst T = f();`,
        "a,c",
      ],
      [
        `function add(o){ o.x = "b"; return "k"; } function pick(a){ return a; } function f(){ const o = {x:"a"}; o.y = pick("k", add(o)); return o; }\nconst T = f();`,
        "b",
      ],
    ];
    for (const [source, truth] of cases) truthOrNothing(source, truth);
  });

  it("M1: a var declared again in a nested block or loop is the function's variable", () => {
    truthOrNothing(
      `function f(){ var s = "a"; { var s = "b"; } const o = {}; o.x = s; return o; }\nconst T = f();`,
      "b",
    );
    truthOrNothing(
      `function f(){ var s = "a"; for (const p of ["b"]) { var s = p; } const o = {}; o.x = s; return o; }\nconst T = f();`,
      "b",
    );
  });

  it("M2: a const of an inner block does not reach the code after the block", () => {
    truthOrNothing(
      `const N = "top"; function make(){ const o = {}; { const N = "inner"; } o.x = N; return o; }\nconst T = make();`,
      "top",
    );
    // inside its own block it is the inner one
    expect(
      channels(`function f() { if (ok) { const ch = "in:block"; ipcMain.on(ch, g); } }`),
    ).toEqual(["in:block"]);
  });

  it("M3: keeps the key order JavaScript has", () => {
    truthOrNothing(
      `function f(){ const o = {a:"1", b:"2"}; o.a = "3"; const r = {}; for (const k in o) r.x = k; return r; }\nconst T = f();`,
      "b",
    );
    truthOrNothing(
      `function f(){ const o = {b:"1", "2":"2"}; const r = {}; for (const k in o) r.x = k; return r; }\nconst T = f();`,
      "b",
    );
    truthOrNothing(
      `function f(){ const o = Object.fromEntries([["a","1"],["b","2"],["a","3"]]); const r = {}; for (const k in o) r.x = k; return r; }\nconst T = f();`,
      "b",
    );
    truthOrNothing(
      `function f(){ const o = {a:"1", b:"2", a:"3"}; const r = {}; for (const k in o) r.x = k; return r; }\nconst T = f();`,
      "b",
    );
  });

  it("M6: does not evaluate async functions or generators as returning their object", () => {
    truthOrNothing(
      `async function f(){ const r = {}; r.x = "a"; return r; }\nconst T = f();`,
      null,
    );
    truthOrNothing(`function* f(){ const r = {}; r.x = "a"; return r; }\nconst T = f();`, null);
    truthOrNothing(
      `const f = async () => { const r = {}; r.x = "a"; return r; };\nconst T = f();`,
      null,
    );
  });

  it("L1: a table changed after it was built is not read", () => {
    const F = `function f(){ const o = {}; o.x = "a"; return o; }\n`;
    for (const after of [
      `const U = T; U.x = "changed";`,
      "mutate(T);",
      "delete T.x;",
      'T.x += "changed";',
    ])
      truthOrNothing(`${F}const T = f();\n${after}`, null);
  });

  it("L1: a table that is only read elsewhere stays known", () => {
    const F = `function f(){ const o = {}; o.x = "a"; return o; }\nconst T = f();\n`;
    const at = (after: string) =>
      scanJavaScript(`const { ipcMain } = require("electron");\n${F}${after}\nipcMain.on(T.x, g);`)
        .ipc[0]!.channel;
    expect(at("const C = Object.assign({}, T, { y: 1 });")).toBe("a");
    expect(at("new Notification({ body: T });")).toBe("a");
    expect(at("function read(t) { return t.x; }\nread(T);")).toBe("a");
    expect(at('function write(t) { t.x = "b"; }\nwrite(T);')).toBeNull();
    expect(at("Object.assign(T, { x: 1 });")).toBeNull();
    expect(at("class Box { constructor(t) { t.x = 1; } }\nnew Box(T);")).toBeNull();
  });

  it("L3: decodes escapes in string literals", () => {
    expect(literalAt(String.raw`"a\x41"`)).toBe("aA");
    expect(literalAt('"a\\u0041"')).toBe("aA");
    expect(literalAt(String.raw`"a\u{41}"`)).toBe("aA");
    expect(literalAt('"a\\\nb"')).toBe("ab");
    expect(literalAt(String.raw`'a\0b'`)).toBe("a\0b");
    expect(literalAt(String.raw`"a\nb"`)).toBe("a\nb");
    expect(literalAt(String.raw`"a\\b"`)).toBe("a\\b");
  });
});
